from typing import Callable, Dict

Registry = Dict[str, Callable]
registry: Registry = {}

def register(name: str, fn: Callable):
    registry[name] = fn

def invoke(name: str, payload: dict):
    if name not in registry:
        raise ValueError("Unknown module")
    return registry[name](payload)

export type Contract<TIn, TOut> = {
  name: string
  validateInput: (input: TIn) => boolean
  execute: (input: TIn) => TOut
}

export function runContract<TIn, TOut>(c: Contract<TIn, TOut>, input: TIn): TOut {
  if (!c.validateInput(input)) throw new Error("Invalid input")
  return c.execute(input)
}
